package com.buildertoolbox.client.settings; import java.util.*; public final class Settings implements Iterable<SettingGroup> {private final List<SettingGroup> list=new ArrayList<>(); public Settings(){createGroup("General");} public SettingGroup createGroup(String n){var g=new SettingGroup(n);list.add(g);return g;} public SettingGroup getDefaultGroup(){return list.getFirst();} public Iterator<SettingGroup> iterator(){return list.iterator();} }